import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { verifyV2 } from '../src/core/verify-v2.mjs';

// Independent audit inputs were captured before repair, not generated by the
// implementation or its fixture constructors. Expected verdicts below are
// literal consumer-contract expectations; frozen actual verdicts are unused.
async function captured(path) {
  const record = JSON.parse(await readFile(new URL(`../reports/release-audit-v0.2/${path}`, import.meta.url), 'utf8'));
  return record.pair ?? record.input;
}
const continuity = await captured('core/results/continuity-binding-false.json');
const interpoll = await captured('domains/requirement-admission/interpoll_unknown_fresh_requirement.json');
delete interpoll.request.adapter_requirement.require_fresh_admission;
const prf = await captured('domains/requirement-admission/prf_unknown_policy_requirement.json');
delete prf.request.guarantee_requirement.required_policy_version;
const clone = value => structuredClone(value);
async function rejected(pair) {
  const report = await verifyV2(pair.request, pair.bundle);
  assert.equal(report.overall, 'REJECTED_MALFORMED', JSON.stringify(report));
  assert.equal(report.layers.INPUT.status, 'REJECTED_MALFORMED');
  assert.ok(report.reason_codes.includes('SCHEMA_MISMATCH'));
  assert.equal(report.layers.RECOMPUTATION.status, 'NOT_RUN');
  return report;
}
function canonicalAuditJson(value) {
  if (Array.isArray(value)) return '[' + value.map(canonicalAuditJson).join(',') + ']';
  if (value && typeof value === 'object') return '{' + Object.keys(value).sort().map(key => JSON.stringify(key) + ':' + canonicalAuditJson(value[key])).join(',') + '}';
  return JSON.stringify(value);
}

for (const id of ['continuity-binding-_true_', 'continuity-binding-1', 'continuity-binding-__', 'continuity-binding-null', 'continuity-unknown-option', 'continuity-unknown-policy']) {
  test(`release admission rejects frozen fail-open ${id}`, async () => {
    await rejected(await captured(`core/results/${id}.json`));
  });
}
for (const id of ['interpoll_unknown_fresh_requirement', 'interpoll_unknown_server_requirement', 'interpoll_null_outcome', 'prf_unknown_policy_requirement', 'prf_unknown_evidence_requirement', 'prf_null_known_requirement']) {
  test(`release admission rejects captured unsupported requirement ${id}`, async () => {
    await rejected(await captured(`domains/requirement-admission/${id}.json`));
  });
}

test('release admission preserves limited continuity with Boolean false', async () => {
  const pair = clone(continuity), report = await verifyV2(pair.request, pair.bundle);
  assert.equal(report.overall, 'VERIFIED');
  assert.equal(report.layers.CONTINUITY.status, 'PRESERVED');
  assert.equal(report.layers.CONTINUITY.nativeResult.whole_envelope_binding, 'NOT_ESTABLISHED');
});
test('release admission Boolean true without envelope evidence stays insufficient', async () => {
  const pair = clone(continuity); pair.request.continuity_request.require_whole_envelope_binding = true;
  const report = await verifyV2(pair.request, pair.bundle);
  assert.equal(report.overall, 'INSUFFICIENT_EVIDENCE');
  assert.equal(report.layers.CONTINUITY.status, 'UNVERIFIABLE');
  assert.ok(report.reason_codes.includes('WHOLE_OBSERVATION_ENVELOPE_NOT_BOUND'));
});
test('release admission Boolean true plus independently hashed envelope remains preserved', async () => {
  const pair = clone(continuity); pair.request.continuity_request.require_whole_envelope_binding = true;
  pair.request.continuity_request.observation_envelope_digest = createHash('sha256').update(canonicalAuditJson(pair.bundle.payload.continuity), 'utf8').digest('hex');
  const report = await verifyV2(pair.request, pair.bundle);
  assert.equal(report.overall, 'VERIFIED');
  assert.equal(report.layers.CONTINUITY.status, 'PRESERVED');
  assert.equal(report.layers.CONTINUITY.nativeResult.whole_envelope_binding, 'BOUND');
});
test('release admission supported Interpoll request retains valid native signature and exact relation', async () => {
  const pair = clone(interpoll), report = await verifyV2(pair.request, pair.bundle);
  assert.equal(report.overall, 'VERIFIED');
  assert.equal(report.layers.DOMAIN_ADAPTERS.nativeResult.signature, 'VALID');
  assert.equal(report.layers.DOMAIN_ADAPTERS.nativeResult.execution, 'OBSERVATION_SUPPLIED');
  assert.equal(report.layers.DOMAIN_ADAPTERS.nativeResult.admission, 'NOT_EVALUATED');
});
test('release admission only omitted Interpoll outcome receives the existing default', async () => {
  const pair = clone(interpoll); delete pair.request.adapter_requirement.required_outcome;
  const report = await verifyV2(pair.request, pair.bundle);
  assert.equal(report.overall, 'VERIFIED');
  assert.equal(report.layers.DOMAIN_ADAPTERS.nativeResult.execution, 'OBSERVATION_SUPPLIED');
});
test('release admission missing Interpoll context keeps insufficient evidence behavior', async () => {
  const pair = clone(interpoll); delete pair.request.adapter_requirement;
  const report = await verifyV2(pair.request, pair.bundle);
  assert.equal(report.overall, 'INSUFFICIENT_EVIDENCE');
  assert.ok(report.reason_codes.includes('CALLER_ACTION_REQUIRED'));
});
test('release admission empty supported Interpoll context keeps insufficient evidence behavior', async () => {
  const pair = clone(interpoll); pair.request.adapter_requirement = {};
  const report = await verifyV2(pair.request, pair.bundle);
  assert.equal(report.overall, 'INSUFFICIENT_EVIDENCE');
  assert.ok(report.reason_codes.includes('CALLER_ACTION_REQUIRED'));
});
test('release admission typed different requested action remains a semantic contradiction', async () => {
  const pair = clone(interpoll); pair.request.adapter_requirement.requested_action.targetId = 'other-target';
  const report = await verifyV2(pair.request, pair.bundle);
  assert.equal(report.overall, 'CONTRADICTED');
  assert.ok(report.reason_codes.includes('SIGNED_INTENT_REQUEST_MISMATCH'));
});
test('release admission supported PRF requirement preserves native tuple and transfer separately', async () => {
  const pair = clone(prf), report = await verifyV2(pair.request, pair.bundle);
  assert.equal(report.overall, 'VERIFIED');
  assert.equal(report.layers.GUARANTEE_PRESERVATION.status, 'PRESERVED');
  assert.deepEqual(report.layers.GUARANTEE_PRESERVATION.nativeResult.recomputed, { outcome: 'PRESERVED', reason: 'award_bound_to_actual_settlement' });
});
test('release admission absent PRF context keeps selector insufficiency behavior', async () => {
  const pair = clone(prf); delete pair.request.guarantee_requirement;
  const report = await verifyV2(pair.request, pair.bundle);
  assert.equal(report.overall, 'INSUFFICIENT_EVIDENCE');
  assert.ok(report.reason_codes.includes('PRF_RELATION_SELECTOR_REQUIRED'));
});
test('release admission typed unsupported PRF guarantee stays explicitly unsupported', async () => {
  const pair = clone(prf); pair.request.guarantee_requirement.required_guarantee = 'unsupported-guarantee.v99';
  const report = await verifyV2(pair.request, pair.bundle);
  assert.equal(report.overall, 'UNSUPPORTED_PROFILE');
  assert.ok(report.reason_codes.includes('PRF_GUARANTEE_UNSUPPORTED'));
});
test('release admission valid inactive PRF context makes no unrequested guarantee claim', async () => {
  const pair = clone(prf); pair.request.requested_guarantees = [];
  const report = await verifyV2(pair.request, pair.bundle);
  assert.equal(report.overall, 'VERIFIED');
  assert.equal(report.layers.GUARANTEE_PRESERVATION.status, 'NOT_REQUESTED');
  assert.equal(report.layers.GUARANTEE_PRESERVATION.nativeResult, null);
});

for (const [name, fixture, change] of [
  ['null continuity context', continuity, p => { p.request.continuity_request = null; }],
  ['unknown continuity mode', continuity, p => { p.request.continuity_request.mode = 'global-latest'; }],
  ['null continuity subject selector', continuity, p => { p.request.continuity_request.entry_id = null; }],
  ['nonstring continuity root reference', continuity, p => { p.request.continuity_request.receipt_root = true; }],
  ['null Interpoll context', interpoll, p => { p.request.adapter_requirement = null; }],
  ['extra Interpoll requested action field', interpoll, p => { p.request.adapter_requirement.requested_action.fresh = true; }],
  ['missing Interpoll action nonce', interpoll, p => { delete p.request.adapter_requirement.requested_action.nonce; }],
  ['wrong Interpoll material parameter type', interpoll, p => { p.request.adapter_requirement.requested_action.createdAt = '123'; }],
  ['extra Interpoll authority field', interpoll, p => { p.request.adapter_requirement.authority.server = 'attested'; }],
  ['wrong Interpoll authority type', interpoll, p => { p.request.adapter_requirement.authority.actor = false; }],
  ['unsupported Interpoll outcome', interpoll, p => { p.request.adapter_requirement.required_outcome = 'FRESH_SERVER_EXECUTION'; }],
  ['null PRF context', prf, p => { p.request.guarantee_requirement = null; }],
  ['extra PRF accepted basis field', prf, p => { p.request.guarantee_requirement.accepted_basis.chain = 'ethereum'; }],
  ['wrong PRF dependency version type', prf, p => { p.request.guarantee_requirement.accepted_basis.dependencies[0].version = 1; }],
  ['extra PRF dependency field', prf, p => { p.request.guarantee_requirement.accepted_basis.dependencies[0].authority = 'server'; }],
  ['extra PRF native result field', prf, p => { p.request.guarantee_requirement.required_native_result.authentic = true; }],
  ['wrong PRF native vocabulary', prf, p => { p.request.guarantee_requirement.required_native_result.outcome = 'PASS'; }],
  ['wrong PRF tuple selector type', prf, p => { p.request.guarantee_requirement.required_relation_input_digest = null; }],
]) {
  test(`release admission refuses ${name} before semantic execution`, async () => {
    const pair = clone(fixture); change(pair); await rejected(pair);
  });
}
test('release admission rejects ambiguous accepted PRF dependency identities', async () => {
  const pair = clone(prf), dep = clone(pair.request.guarantee_requirement.accepted_basis.dependencies[0]);
  dep.version = 'other'; pair.request.guarantee_requirement.accepted_basis.dependencies.push(dep);
  const report = await verifyV2(pair.request, pair.bundle);
  assert.equal(report.overall, 'REJECTED_MALFORMED');
  assert.ok(report.reason_codes.includes('DEPENDENCY_ID_DUPLICATE'));
});
